from lib import *
from fractions import Fraction as F
LESSON = 'ប្រូបាប'
def fr(f):
    f = F(f)
    return M(str(f.numerator)) if f.denominator == 1 else M(f'\\dfrac{{{f.numerator}}}{{{f.denominator}}}')
def pct(f):
    v = F(f) * 100
    return M((str(v.numerator) if v.denominator == 1 else f'{float(v):g}') + '\\%')
