    C.append(wr('pisa', 'pisa', 'ថាសបង្វិលមួយចែក ' + M(8) + ' ផ្នែកស្មើគ្នា លេខ ' + M('1') + ' ដល់ ' + M('8') + '។ ក. ប្រូបាបបានលេខសេស។ ខ. ប្រូបាបបានលេខធំជាង ' + M(6) + '។ គ. ប្រូបាបបានលេខ ' + M('9') + '។', [('ក. ' + M('\\dfrac{4}{8} = \\dfrac{1}{2}'), 1), ('ខ. ' + M('7, 8 \\Rightarrow \\dfrac{2}{8} = \\dfrac{1}{4}'), 2), ('គ. ' + M('P = 0'), 2)]))
    C.append(wr('pisa', 'pisa', 'ក្នុងកំប៉ុងមួយមានគ្រាប់ស្ករពណ៌ក្រហម ' + M(12) + ' លឿង ' + M(8) + ' បៃតង ' + M(5) + '។ ក. ប្រូបាបចាប់បានក្រហម។ ខ. បើគេយកក្រហម ' + M(2) + ' គ្រាប់ចេញ ប្រូបាបថ្មីនៃក្រហម? គ. តើប្រូបាបកើនឬថយ?', [('ក. ' + M('\\dfrac{12}{25} = 48\\%'), 2), ('ខ. ' + M('\\dfrac{10}{23} \\approx 43.5\\%'), 2), ('គ. ថយ (' + M('48\\% \\to 43.5\\%') + ')', 1)]))
    C.append(wr('pisa', 'pisa', 'ក្រុមបាល់ទាត់ឈ្នះ ' + M(18) + ' ប្រកួត ស្មើ ' + M(6) + ' ចាញ់ ' + M(6) + ' ក្នុងរដូវកាលនេះ។ ក. ប្រូបាបជាក់ស្តែងនៃការឈ្នះ។ ខ. តើក្រុមនេះអាចឈ្នះប្រហែលប៉ុន្មាន ក្នុង ' + M(10) + ' ប្រកួតថ្មី?', [('ក. ' + M('\\dfrac{18}{30} = 60\\%'), 2), ('ខ. ' + M('10 \\times 0.6 = 6') + ' ប្រកួត (ប្រហែល)', 3)]))
